"""Only four authenticated historical private table roles may use the exact public replacement."""
from pathlib import Path
import subprocess
import unittest
ROOT=Path(__file__).resolve().parents[1]
class TableDefinitionContextTests(unittest.TestCase):
    def test_original_contract_public_object_and_mandatory_behavior_receipt(self):
        code=r'''
import assert from 'node:assert/strict';import {originalFactoryContract} from './scripts/api-surface.mjs';import {originalCompilerFactoryContext,originalContextDi} from './scripts/api-original-factory-contexts.mjs';import {tableDefinitionContract,tableDefinitionTokenMatches,tableDefinitionObservationProblems} from './scripts/api-table-definition-context.mjs';import {runtimeTokenIdentity} from './scripts/api-di-observe.mjs';
let originals=0,identities=0,receipts=0;
for(const name of ['MatLegacyColumnDef','MatLegacyHeaderRowDef','MatLegacyFooterRowDef','MatLegacyRowDef']){
 const originalFactory=originalFactoryContract('/original/src/material/legacy-table/'+(name==='MatLegacyColumnDef'?'cell':'row')+'.ts',name),symbol={symbol_id:'legacy-table/primary/'+name,family:'legacy-table',kind:'primary',name,shape:{originalFactory,originalFactoryContext:originalCompilerFactoryContext(originalFactory)}};
 const contract=tableDefinitionContract(symbol),param=originalContextDi(symbol.shape)[contract.table_index];assert.equal(contract.constructor_arity,name==='MatLegacyColumnDef'?1:3);assert.equal(contract.original_ident,'CDK_TABLE');
 for(const change of [x=>x.family='foreign',x=>x.kind='testing',x=>x.name='Foreign',x=>x.shape.originalFactory.declaration+=' ',x=>x.shape.originalFactoryContext.parameter_factory_key='foreign',x=>x.shape.originalFactoryContext.factory_parameters[contract.table_index].optional=false,x=>x.shape.originalFactoryContext.factory_parameters[contract.table_index].spec='@angular/cdk/table',x=>x.shape.originalFactoryContext.factory_parameters.pop(),x=>x.shape.originalFactoryContext.source_sha256='0'.repeat(64)]){const bad=structuredClone(symbol);change(bad);assert.throws(()=>tableDefinitionContract(bad));originals++;}
 class CdkTable{}class Twin{}class OwnedAlias{};const loader=async spec=>{assert.equal(spec,'@angular/cdk/table');return {CdkTable};};assert.equal(tableDefinitionTokenMatches(symbol,param,{CdkTable},CdkTable),true);assert.equal(await runtimeTokenIdentity(symbol.family,param,{CDK_TABLE:OwnedAlias},{CDK_TABLE:['CDK_TABLE']},CdkTable,loader,null,symbol),true);
 for(const token of [Twin,OwnedAlias,{},null]){assert.equal(tableDefinitionTokenMatches(symbol,param,{CdkTable},token),false);assert.equal(await runtimeTokenIdentity(symbol.family,param,{CDK_TABLE:OwnedAlias},{},token,loader,null,symbol),false);identities++;}
 for(const change of [p=>p.optional=false,p=>p.spec='@angular/cdk/table',p=>p.self=true,p=>p.imported='CdkTable']){const bad=structuredClone(param);change(bad);assert.throws(()=>tableDefinitionTokenMatches(symbol,bad,{CdkTable},CdkTable));identities++;}
 const checks=contract.table_index===0?['historical-name-sanitization-dual-class-prefix-and-empty-write','sticky-historical-direct-write-coercion-and-dirty-read-reset','stickyEnd-historical-direct-write-coercion-and-dirty-read-reset']:['actual-public-iterable-differ-add-remove-and-stable-repeat','actual-owned-cell-template-selection','actual-template-view-context-and-disposal',name==='MatLegacyRowDef'?'public-row-predicate-retained':'sticky-historical-direct-write-coercion-and-dirty-read-reset'];
 const x={contract,constructor_calls:1,constructor_arity:contract.constructor_arity,table_kind:'legacy',public_parent_identity_matched:true,original_supplied_inputs_identical:true,parent_provider_scope_verified:true,manual_outside_di_preserved:true,consumer_subclass_preserved:true,actual_parent_query_initialized:true,checks:checks.map(id=>({id,result:'pass'})),borrowed_table_destroy_calls:0,borrowed_context_alive:true,borrowed_table_public_render_control:true};
 const request={expected_ident:'CDK_TABLE',expected_spec:null,identity_matched:true,unresolved:false,optional:true,expected_optional:true,self:false,expected_self:false,skipSelf:false,expected_skipSelf:false,host:false,expected_host:false,table_definition_token_role:contract};const row={symbol,factory_outcome:'returned',factory_table_definition_context:x,runtime_requests:Array.from({length:contract.constructor_arity},()=>null)};row.runtime_requests[contract.table_index]=request;assert.deepEqual(tableDefinitionObservationProblems(row),[]);
 for(const change of [x=>x.contract.public_export='OwnedAlias',x=>x.contract.public_spec='foreign',x=>x.contract.table_index++,x=>x.contract.original_ident='CdkTable',x=>x.contract.constructor_arity++,x=>x.contract.extra='waiver',x=>x.constructor_calls++,x=>x.constructor_arity++,x=>x.table_kind='peer',x=>x.public_parent_identity_matched=false,x=>x.original_supplied_inputs_identical=false,x=>x.parent_provider_scope_verified=false,x=>x.manual_outside_di_preserved=false,x=>x.consumer_subclass_preserved=false,x=>x.actual_parent_query_initialized=false,x=>x.checks.pop(),x=>x.checks.reverse(),x=>x.checks[0].result='skipped',x=>x.borrowed_table_destroy_calls++,x=>x.borrowed_context_alive=false,x=>x.borrowed_table_public_render_control=false,x=>x.extra='waiver']){const bad=structuredClone(row);change(bad.factory_table_definition_context);assert.ok(tableDefinitionObservationProblems(bad).length);receipts++;}
 for(const change of [r=>r.expected_ident='CdkTable',r=>r.expected_spec='@angular/cdk/table',r=>r.identity_matched=false,r=>r.unresolved=true,r=>r.optional=false,r=>r.expected_optional=false,r=>r.self=true,r=>r.skipSelf=true,r=>r.host=true,r=>r.expected_self=true,r=>r.expected_skipSelf=true,r=>r.expected_host=true,r=>delete r.table_definition_token_role,r=>r.table_definition_token_role.extra='waiver']){const bad=structuredClone(row);change(bad.runtime_requests[contract.table_index]);assert.ok(tableDefinitionObservationProblems(bad).length);receipts++;}
 const missing=structuredClone(row);delete missing.factory_table_definition_context;assert.ok(tableDefinitionObservationProblems(missing).length);receipts++;
}
assert.equal(originals,36);assert.equal(identities,32);assert.equal(receipts,148);for(const id of ['foreign','constructor','__proto__'])assert.equal(tableDefinitionContract({symbol_id:id}),null);
'''
        result=subprocess.run(['node','--input-type=module','-e',code],cwd=ROOT,capture_output=True,text=True,timeout=10)
        self.assertEqual(result.returncode,0,(result.stdout+result.stderr)[-5500:])
